export type Pagefind = {
  init?(): Promise<void>;
  search(q: string): Promise<{
    results: {
      id: string;
      data(): Promise<{ url: string; meta: Record<string, string> }>;
    }[];
  }>;
};

let memo: Promise<Pagefind | null> | undefined;

/** Loads the static Pagefind runtime once; null when the index is not there (e.g. `next dev`). */
export function loadPagefind(): Promise<Pagefind | null> {
  memo ??= (async () => {
    try {
      // prettier-ignore
      // @ts-expect-error -- generated by postbuild; absent from the type graph
      const pf: Pagefind = await import(/* webpackIgnore: true */ "/pagefind/pagefind.js");
      await pf.init?.();
      return pf;
    } catch {
      return null;
    }
  })();
  return memo;
}
